/**
 * Dedup evaluation: precision and recall for distance-only vs distance+category.
 * Uses ground-truth clusters generated by synthetic.ts.
 * Prints results to stdout; no fabricated numbers.
 */
import { generateSyntheticIssues } from "./synthetic.js";
import { IssueRepo } from "./issue-repo.js";
import { haversineMetres, scoreDuplicate } from "../domain/algorithms.js";
import { connectMongo } from "./mongo.js";

interface Metric {
  tp: number;
  fp: number;
  fn: number;
}

function prf({ tp, fp, fn }: Metric) {
  const precision = tp + fp > 0 ? tp / (tp + fp) : 0;
  const recall = tp + fn > 0 ? tp / (tp + fn) : 0;
  const f1 = precision + recall > 0 ? (2 * precision * recall) / (precision + recall) : 0;
  return { precision, recall, f1 };
}

async function evalDedup(): Promise<void> {
  await connectMongo();
  const clusters = await generateSyntheticIssues({
    issuesPerCluster: 6,
    clustersPerTenant: 5,
    nearMissPerCluster: 2,
  });

  const distOnly: Metric = { tp: 0, fp: 0, fn: 0 };
  const distPlusCat: Metric = { tp: 0, fp: 0, fn: 0 };

  for (const cluster of clusters) {
    if (cluster.issueIds.length < 2) continue;
    const repo = new IssueRepo(cluster.tenantId);

    // Use first issue as probe
    const probeId = cluster.issueIds[0]!;
    const truePositiveIds = new Set(cluster.issueIds.slice(1));
    const falsePosIds = new Set(cluster.nearMissIds);

    const probe = await repo.findByPublicId(probeId);
    if (!probe) continue;

    const [lon, lat] = probe.location.coordinates;
    const rEff = (probe.category as { dedupRadiusM: number }).dedupRadiusM + 15; // avg GPS noise

    const candidates = await repo.findGeoNearCandidates(lon, lat, rEff * 3, probeId);

    for (const { issue: candidate } of candidates) {
      const dist = haversineMetres(
        lat,
        lon,
        candidate.location.coordinates[1],
        candidate.location.coordinates[0]
      );

      const distScore = scoreDuplicate({
        distanceM: dist,
        rEff,
        sameCategory: true,
        compatibleCategory: false,
      });
      const catScore = scoreDuplicate({
        distanceM: dist,
        rEff,
        sameCategory:
          (candidate.category as { code: string }).code ===
          (probe.category as { code: string }).code,
        compatibleCategory: false,
      });

      const isTruePos = truePositiveIds.has(candidate.publicId);
      const isNearMiss = falsePosIds.has(candidate.publicId);

      // Distance-only baseline
      if (distScore.suggestion) {
        if (isTruePos) distOnly.tp++;
        else if (isNearMiss) distOnly.fp++;
      } else {
        if (isTruePos) distOnly.fn++;
      }

      // Distance + category
      if (catScore.suggestion) {
        if (isTruePos) distPlusCat.tp++;
        else if (isNearMiss) distPlusCat.fp++;
      } else {
        if (isTruePos) distPlusCat.fn++;
      }
    }
  }

  const distResult = prf(distOnly);
  const catResult = prf(distPlusCat);

  console.log("\n=== Dedup Evaluation Results ===");
  console.log(`Clusters: ${clusters.length}, threshold: 0.55`);
  console.log(
    `Distance-only:          P=${distResult.precision.toFixed(3)} R=${distResult.recall.toFixed(3)} F1=${distResult.f1.toFixed(3)}`
  );
  console.log(
    `Distance + Category:    P=${catResult.precision.toFixed(3)} R=${catResult.recall.toFixed(3)} F1=${catResult.f1.toFixed(3)}`
  );
  console.log("================================\n");
}

evalDedup()
  .then(() => process.exit(0))
  .catch((err) => {
    console.error("eval-dedup failed:", err);
    process.exit(1);
  });
